<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),mode=ref('overall'),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.fnusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const labels=['Signup','Activate','Invite','Pay']
const values=computed(()=>dataset.value==='A'?[100,75,50,20]:dataset.value==='B'?[80,40,10,0]:dataset.value==='equal'?[50,50,50,50]:[0,0,0,0])
const rate=(i:number,which:string)=>{const denominator=which==='overall'?values.value[0]:i?values.value[i-1]:values.value[0];return denominator?100*values.value[i]/denominator:null}
const fmt=(v:number|null)=>v===null?'N/A':v.toFixed(1)+'%'
function reset(){dataset.value='A';state.value='ready';selected.value=0;mode.value='overall'}
</script>
<template>
<section ref="root" class="fnusage-demo" aria-label="Local funnel example"><p>Synthetic nested signup cohort reaching four ordered stages. Same people, same observation window; each later stage is a subset of the prior stage. Centered bar width is count on a fixed 0–100 axis, never a sum of stage counts.</p><div class="fnusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="equal">No drop-off</option><option value="zero">No entrants</option></select></label><label>Readout rate<select v-model="mode"><option value="overall">Overall</option><option value="step">Previous step</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="fnusage-card"><template v-if="state==='ready'"><svg viewBox="0 0 330 260" role="img" aria-label="Four centered equal-height stage bars. Full width encodes count on fixed zero to one hundred scale, not segment area or selected rate."><line class="fnusage-grid" x1="160" x2="160" y1="24" y2="211"/><g v-for="(v,i) in values" :key="labels[i]" class="fnusage-row" :class="{selected:selected===i}"><rect v-if="v>0" class="fnusage-bar" :x="160-v*1.2" :y="29+45*i" :width="v*2.4" height="28" rx="4" data-cm="fade"/><line v-else class="fnusage-zero" x1="156" x2="164" :y1="43+45*i" :y2="43+45*i"/><text x="40" :y="25+45*i">{{ labels[i] }}</text><text :x="v>=20?160:290" :y="47+45*i" :text-anchor="v>=20?'middle':'end'" :class="v>=20?'fnusage-inverse':''">{{ v }}</text></g><text x="160" y="231" text-anchor="middle">Full width: 0–100 people</text><text x="160" y="250" text-anchor="middle">First-stage count: {{ values[0] }}</text></svg><div role="group" aria-label="Select stage" class="fnusage-choices"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @focus="selected=i" @click="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: {{ values[selected] }} people; {{ mode==='overall'?'overall':'previous-step' }} rate {{ fmt(rate(selected,mode)) }}; {{ selected?values[selected-1]-values[selected]:'N/A' }} lost since previous stage.</p><table class="fnusage-data"><caption>Exact nested stage counts, dataset {{ dataset }}</caption><thead><tr><th scope="col">Stage</th><th scope="col">Count</th><th scope="col">Overall</th><th scope="col">Step</th></tr></thead><tbody><tr v-for="(v,i) in values" :key="labels[i]"><th scope="row">{{ labels[i] }}</th><td>{{ v }}</td><td>{{ fmt(rate(i,'overall')) }}</td><td>{{ fmt(rate(i,'step')) }}</td></tr></tbody></table><p class="fnusage-key">Overall divides by Signup; step divides by the previous count (Signup uses itself). A zero numerator with positive denominator is 0%; 0/0 is undefined. Counts are nested, so adding bars double-counts people. Zero has no positive-width bar; the center tick locates it. Rate mode changes the readout, not the count geometry.</p></template><p v-else role="status" class="fnusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Stage counts are withheld.':'No funnel records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>
.fnusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.fnusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.fnusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.fnusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.fnusage-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.fnusage-demo :is(button,select):focus-visible{outline:2px solid var(--vp-c-brand-1);outline-offset:3px}.fnusage-demo svg{display:block;width:100%;height:auto;max-height:360px;margin:16px 0}.fnusage-demo svg text{fill:var(--vp-c-text-2);font-size:11px}.fnusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 3}.fnusage-row{opacity:.7}.fnusage-row.selected{opacity:1}.fnusage-bar{fill:#6366f1;stroke:var(--vp-c-text-1);stroke-width:1}.fnusage-demo svg .fnusage-inverse{fill:white}.fnusage-zero{stroke:var(--vp-c-text-1);stroke-width:2}.fnusage-choices{display:flex;gap:6px;flex-wrap:wrap}.fnusage-demo button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.fnusage-data{display:table!important;width:100%;font-size:12px}.fnusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.fnusage-data :is(td,th){padding:6px!important}.fnusage-key{font-size:12px;color:var(--vp-c-text-2)}.fnusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}
</style>
